<h2>Immutable work history</h2><ol class="damage-history"><?php foreach ($events as $event): $snapshot = json_decode($event['after_json'], true, 512, JSON_THROW_ON_ERROR); ?><li><strong><?= esc(ucwords(str_replace('_', ' ', $event['event_code']))) ?></strong> · Version <?= (int) $event['job_version'] ?> · <?= esc((string) $event['recorded_at']) ?> · Operator <?= (int) $event['actor_user_id'] ?><p>Occurrence: <?= esc((string) ($event['occurred_at'] ?? 'Exact time unknown / not applicable')) ?></p><?php if ($event['reason'] !== null): ?><p><?= nl2br(esc($event['reason'])) ?></p><?php endif; ?><details><summary>Recorded work state and outcomes</summary><p><?= esc($snapshot['job']['summary']) ?> · <?= esc(\Config\VehicleDamage::WORK_STATUSES[$snapshot['job']['status_code']]) ?></p><p>Started: <?= esc((string) ($snapshot['job']['started_at'] ?? 'Not recorded')) ?> · Completed: <?= esc((string) ($snapshot['job']['completed_at'] ?? 'Not recorded')) ?></p><?php if ($snapshot['job']['completion_note'] !== null): ?><p><?= nl2br(esc($snapshot['job']['completion_note'])) ?></p><?php endif; ?><ul><?php foreach ($snapshot['members'] as $entry): ?><li>Condition <?= (int) $entry['vehicle_damage_item_id'] ?> · <?= esc(\Config\VehicleDamage::WORK_RESULTS[$entry['result_code']]) ?><?= $entry['withdrawn_at'] === null ? '' : ' · Withdrawn' ?><?php if ($entry['note'] !== null): ?><p><?= nl2br(esc($entry['note'])) ?></p><?php endif; ?></li><?php endforeach; ?></ul><?php if (isset($snapshot['b22'])): ?><h4>Recorded estimate and document state</h4><p>Accepted estimate: <?= isset($snapshot['job']['accepted_estimate_id']) ? (int) $snapshot['job']['accepted_estimate_id'] : 'None' ?></p><ul><?php foreach ($snapshot['b22']['estimates'] as $quote): ?><li>Estimate <?= (int) $quote['id'] ?> &middot; <?= esc($quote['currency']) ?> <?= esc($quote['amount']) ?> &middot; <?= esc($quote['vendor_snapshot'] ?? 'Unknown vendor') ?> &middot; Revision <?= (int) $quote['revision_number'] ?> &middot; <?= esc(ucfirst($quote['status_code'])) ?></li><?php endforeach; ?><?php foreach ($snapshot['b22']['documents'] as $source): ?><li>Document <?= (int) $source['id'] ?> &middot; <?= esc($source['kind_code']) ?> &middot; <?= esc($source['label'] ?? $source['content_original_filename'] ?? 'External reference') ?><?= $source['archived_at'] === null ? '' : ' - Archived' ?></li><?php endforeach; ?></ul><?php endif; ?><?php if (isset($snapshot['b23'])): ?><h4>Recorded repair cost state</h4><p>Invoiced work: <?= esc($snapshot['b23']['totals']['invoiced'] ?? 'Unknown') ?> / Vendor payments: <?= esc($snapshot['b23']['totals']['payments'] ?? 'No vendor payments recorded') ?></p><ul><?php foreach ($snapshot['b23']['entries'] as $cost): ?><li><?= esc($cost['kind_code']) ?> <?= (int) $cost['id'] ?> / <?= esc($cost['currency']) ?> <?= esc($cost['amount']) ?> / <?= esc($cost['status_code']) ?> / <?= esc($cost['occurred_on']) ?> / <?= esc($cost['vendor_snapshot']) ?></li><?php endforeach; ?></ul><?php endif; ?><?php if (isset($snapshot['job']['cost_finalized_at'])): ?><p>Invoiced cost finalized: <?= esc($snapshot['job']['cost_finalized_at']) ?> / <?= esc($snapshot['job']['cost_finalization_note']) ?></p><?php endif; ?></details></li><?php endforeach; ?></ol>
